-- SCA Feedback Statements (Domains 1-3), normalized structure
-- Source: https://www.rcgp.org.uk/mrcgp-exams/simulated-consultation-assessment/feedback-statements
-- `standard` and `description` contain cleaned HTML (h3/p/ul/li/strong/em/br only).

DROP TABLE IF EXISTS `sca_feedback_statements`;
DROP TABLE IF EXISTS `sca_feedback_domains`;

CREATE TABLE `sca_feedback_domains` (
  `id` TINYINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(150) NOT NULL,
  `standard` TEXT NOT NULL COMMENT 'Standard for marking (passing level), HTML',
  `sort_order` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sca_feedback_statements` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `domain_id` TINYINT UNSIGNED NOT NULL,
  `sl_no` TINYINT UNSIGNED NOT NULL COMMENT 'Statement number within the domain (as on RCGP page)',
  `subject` VARCHAR(255) NOT NULL,
  `description` TEXT NOT NULL COMMENT 'Educator notes, HTML',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_domain_statement` (`domain_id`,`sl_no`),
  CONSTRAINT `fk_sca_statement_domain` FOREIGN KEY (`domain_id`)
    REFERENCES `sca_feedback_domains` (`id`)
    ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;






























